/**
 * A wall-clock planning deadline stops a work-bounded search only when stopping would publish a priced plan for the
 * root. Before that the search continues to its first priced plan, or to its work limit, or until it is cancelled, or
 * until the overrun has lasted as long as the deadline itself; the overrun is reported on the plan. The budget's test
 * clock places the deadline at an exact search work-unit count and the budget's creation a chosen number of nanoseconds
 * before it; one unit in, the search has started and watches for its first priced plan.
 */
class PackedPlanningDeadlineOverrunTest {

	private static final SimpleValueFactory VALUES = SimpleValueFactory.getInstance();
	private static final String OVERRUN_STOP = "optimizer.cascadesDeadlineOverrunStop";
	private static final String OVERRUN_NANOS = "optimizer.cascadesDeadlineOverrunNanos";
	private static final long NO_DEADLINE = Long.MAX_VALUE;
	/** A deadline length (= grace) no test search reaches: one nanosecond per work unit past the deadline. */
	private static final long LONG_GRACE = 1_000_000L;

	@Test
	void deadlineBeforeAnyPricedRootContinuesToTheFirstPricedRoot() {
		Planned complete = plan(NO_DEADLINE, pricedModel(), 10_000);
		assertTrue(complete.result().exactComplete(), "fixture: without a deadline the search completes");

		Planned planned = plan(1L, pricedModel(), 10_000);
		PackedPlanningResult result = planned.result();

		assertTrue(result.totalPrice().isPresent(), () -> "a priced root plan must be returned: " + result);
		assertEquals("first-priced-plan", result.selectedPlan().getStringMetricPlanned(OVERRUN_STOP));
		assertTrue(result.selectedPlan().getDoubleMetricPlanned(OVERRUN_NANOS) > 0.0d,
				"the time spent past the deadline is reported");
		assertEquals(PackedSearchCompletionStatus.INCOMPLETE_DEADLINE, result.completionStatus());
		assertTrue(planned.pastDeadlineSamples() > 1, "the search went on past the deadline");
		assertTrue(planned.searchWork() < complete.searchWork(),
				() -> "the overrun stops at the first priced root, before the complete search: "
						+ planned.searchWork() + " vs " + complete.searchWork());
	}

	@Test
	void deadlineAfterAPricedRootIsRetainedStopsAtOnceAsBefore() {
		Planned complete = plan(NO_DEADLINE, pricedModel(), 10_000);
		long deadlineAt = complete.searchWork() / 2L;

		Planned planned = plan(deadlineAt, pricedModel(), 10_000);
		PackedPlanningResult result = planned.result();

		assertTrue(result.totalPrice().isPresent(), "fixture: a priced root is retained before the deadline");
		assertNull(result.selectedPlan().getStringMetricPlanned(OVERRUN_STOP), "no overrun");
		assertEquals(PackedSearchCompletionStatus.INCOMPLETE_DEADLINE, result.completionStatus());
		assertEquals(1, planned.pastDeadlineSamples(), "the first sample past the deadline stops the search");
		assertTrue(planned.searchWork() < complete.searchWork(), "the deadline truncates the search");
	}

	/**
	 * The root (a projection) is offered only after the search of its join region, so the root retains no priced plan
	 * while the region is searched; the region's seeded incumbent is priced, and stopping publishes it. The deadline
	 * stops there, as before this overrun existed.
	 */
	@Test
	void deadlineStopsAtOnceWhenTheStopWouldPublishAPricedRegionPlan() {
		Planned planned = plan(projectedChain(), 10L, LONG_GRACE, pricedModel(), 10_000);
		PackedPlanningResult result = planned.result();

		assertTrue(result.totalPrice().isPresent(), "the stop publishes the region's priced incumbent");
		assertNull(result.selectedPlan().getStringMetricPlanned(OVERRUN_STOP), "no overrun");
		assertEquals(PackedSearchCompletionStatus.INCOMPLETE_DEADLINE, result.completionStatus());
		assertEquals(1, planned.pastDeadlineSamples(), "the first sample past the deadline stops the search");
		assertEquals(10L, planned.searchWork(), "no search work after the deadline");
	}

	@Test
	void pricedPlanWithinTheGraceStopsAtTheFirstPricedPlan() {
		Planned planned = plan(filteredChain(), 1L, 10L, pricedModel(), 10_000);
		PackedPlanningResult result = planned.result();

		assertTrue(result.totalPrice().isPresent());
		assertEquals("first-priced-plan", result.selectedPlan().getStringMetricPlanned(OVERRUN_STOP));
		assertTrue(result.selectedPlan().getDoubleMetricPlanned(OVERRUN_NANOS) < 10.0d, "within the grace");
	}

	/**
	 * The deadline lies {@code grace} nanoseconds after the budget's creation, so the overrun ends at twice that time:
	 * at the first deadline sample at or past it, never later, with what a deadline stop returns at that point. This
	 * search samples the deadline at every work unit from 8 to 24, so the end falls exactly on twice the length.
	 */
	@Test
	void overrunWithoutAPricedPlanEndsWhenTheGraceExpires() {
		long deadlineAt = 8L;
		long grace = 5L;
		// Bounded by work, not run to completion: a search in which nothing is priced ends in the correlated
		// lattice's unreachable-target failure, which is not what this test is about.
		Planned longer = plan(filteredChain(), NO_DEADLINE, LONG_GRACE, neverPricedModel(), (int) (deadlineAt + grace + 1));
		assertTrue(longer.searchWork() > deadlineAt + grace, "fixture: the search outlasts the grace");

		Planned planned = plan(filteredChain(), deadlineAt, grace, neverPricedModel(), 10_000);
		PackedPlanningResult result = planned.result();

		assertEquals("grace-expired", result.selectedPlan().getStringMetricPlanned(OVERRUN_STOP));
		assertEquals((double) grace, result.selectedPlan().getDoubleMetricPlanned(OVERRUN_NANOS),
				"the overrun ends exactly at twice the deadline's length");
		assertEquals(1, planned.pastGraceSamples(), "no sample after the grace has expired");
		assertFalse(result.totalPrice().isPresent());
		assertEquals(PackedSearchCompletionStatus.INCOMPLETE_DEADLINE, result.completionStatus());
		Planned stoppedThere = plan(filteredChain(), deadlineAt + grace, 0L, neverPricedModel(), 10_000);
		assertNull(stoppedThere.result().selectedPlan().getStringMetricPlanned(OVERRUN_STOP),
				"fixture: without a grace the deadline stops at once");
		assertEquals(stoppedThere.searchWork(), planned.searchWork());
		assertEquals(shape(stoppedThere.result().selectedPlan()), shape(result.selectedPlan()),
				"what a deadline stop at that point returns");
	}

	@Test
	void deadlineWithoutAnyReachablePricedRootStopsAtTheWorkLimit() {
		int workLimit = 12;
		Planned workLimited = plan(NO_DEADLINE, neverPricedModel(), workLimit);
		assertEquals(PackedSearchCompletionStatus.INCOMPLETE_WORK_LIMIT, workLimited.result().completionStatus(),
				"fixture: the work limit truncates this search");
		assertFalse(workLimited.result().totalPrice().isPresent(), "fixture: no plan of the root is priced");

		Planned planned = plan(filteredChain(), 1L, 100L, neverPricedModel(), workLimit);
		PackedPlanningResult result = planned.result();

		assertFalse(result.totalPrice().isPresent());
		assertEquals("work-limit", result.selectedPlan().getStringMetricPlanned(OVERRUN_STOP),
				"the work limit ends the overrun before the grace does");
		assertTrue(result.selectedPlan().getDoubleMetricPlanned(OVERRUN_NANOS) > 0.0d);
		assertEquals(PackedSearchCompletionStatus.INCOMPLETE_WORK_LIMIT, result.completionStatus());
		assertTrue(planned.searchWork() <= workLimit, "the work limit stays the hard bound");
		assertEquals(workLimited.searchWork(), planned.searchWork(), "the same search as the work-limit stop");
		assertEquals(shape(workLimited.result().selectedPlan()), shape(result.selectedPlan()),
				"the same plan as the work-limit stop without a deadline");
	}

	/**
	 * The boundary of the overrun: a deadline already past before the search starts (before any priced root could be
	 * retained) still stops planning at once with the mandatory written-order fallback, as before.
	 */
	@Test
	void deadlineBeforeTheSearchStartsStillStopsAtOnce() {
		Planned planned = plan(0L, pricedModel(), 10_000);
		PackedPlanningResult result = planned.result();

		assertNull(result.selectedPlan().getStringMetricPlanned(OVERRUN_STOP), "no overrun before the search");
		assertFalse(result.totalPrice().isPresent(), "the evidence-free fallback is returned");
		assertEquals(PackedSearchCompletionStatus.INCOMPLETE_DEADLINE, result.completionStatus());
		assertEquals(0L, planned.searchWork());
	}

	@Test
	void cancellationDuringTheOverrunStopsPlanning() {
		long cancelAt = 3L;
		long[] cancelledAt = { -1L };
		long[] lastSampledWork = { -1L };
		ClockedBudget clock = new ClockedBudget(1L, LONG_GRACE) {
			@Override
			public long applyAsLong(PackedSearchBudget budget) {
				long now = super.applyAsLong(budget);
				lastSampledWork[0] = budget.workUnits();
				if (budget.workUnits() >= cancelAt && cancelledAt[0] < 0L) {
					cancelledAt[0] = budget.workUnits();
					Thread.currentThread().interrupt();
				}
				return now;
			}
		};
		try {
			QueryInterruptedException cancelled = assertThrows(QueryInterruptedException.class,
					() -> clock.plan(filteredChain(), neverPricedModel(), 100_000));
			assertTrue(cancelledAt[0] >= 0L, "fixture: the search ran past the deadline when it was cancelled");
			assertTrue(cancelled.getMessage().contains("past its deadline"),
					() -> "the overrun's own cancellation check stops planning: " + cancelled.getMessage());
			assertEquals(cancelledAt[0], lastSampledWork[0], "no deadline sample after the cancellation");
			assertEquals(cancelledAt[0], clock.budget().workUnits(), "no search work after the cancellation");
		} finally {
			Thread.interrupted();
		}
	}

	private static Planned plan(long deadlineAtWorkUnits, PackedCostModel model, int workLimit) {
		return plan(filteredChain(), deadlineAtWorkUnits, LONG_GRACE, model, workLimit);
	}

	private static Planned plan(TupleExpr expression, long deadlineAtWorkUnits, long grace, PackedCostModel model,
			int workLimit) {
		ClockedBudget clock = new ClockedBudget(deadlineAtWorkUnits, grace);
		PackedPlanningResult result = clock.plan(expression, model, workLimit);
		return new Planned(result, clock.budget().workUnits(), clock.pastDeadlineSamples(),
				clock.pastGraceSamples());
	}

	private record Planned(PackedPlanningResult result, long searchWork, int pastDeadlineSamples,
			int pastGraceSamples) {
	}

	/**
	 * Test clock of one planning. A budget's first reading (at its creation) is {@code grace} nanoseconds before its
	 * deadline, so the deadline's length is {@code grace}; the deadline is reached once {@code deadlineAtWorkUnits}
	 * search work units are charged, and the clock then advances one nanosecond per further unit.
	 */
	private static class ClockedBudget implements ToLongFunction<PackedSearchBudget> {
		private final long deadlineAtWorkUnits;
		private final long grace;
		private final Set<PackedSearchBudget> created = Collections.newSetFromMap(new IdentityHashMap<>());
		private PackedSearchBudget budget;
		private int pastDeadlineSamples;
		private int pastGraceSamples;

		ClockedBudget(long deadlineAtWorkUnits, long grace) {
			this.deadlineAtWorkUnits = deadlineAtWorkUnits;
			this.grace = grace;
		}

		@Override
		public long applyAsLong(PackedSearchBudget sampled) {
			budget = sampled;
			if (created.add(sampled)) {
				return sampled.deadlineNanos() - grace;
			}
			if (sampled.workUnits() < deadlineAtWorkUnits) {
				return sampled.deadlineNanos() - 1L;
			}
			pastDeadlineSamples++;
			if (sampled.workUnits() - deadlineAtWorkUnits >= grace) {
				pastGraceSamples++;
			}
			return sampled.deadlineNanos() + (sampled.workUnits() - deadlineAtWorkUnits);
		}

		PackedPlanningResult plan(TupleExpr expression, PackedCostModel model, int workLimit) {
			PackedSearchBudget.CLOCK_FOR_TESTS.set(this);
			try {
				OptimizationGoal goal = OptimizationGoal.root().asBudgeted(Duration.ofMinutes(10), workLimit);
				return PackedCascadesPlanner.optimize(expression.clone(), goal, model);
			} finally {
				PackedSearchBudget.CLOCK_FOR_TESTS.remove();
			}
		}

		PackedSearchBudget budget() {
			return budget;
		}

		int pastDeadlineSamples() {
			return pastDeadlineSamples;
		}

		int pastGraceSamples() {
			return pastGraceSamples;
		}
	}

	/** FILTER(?v2 = urn:x) over ?v0 p1 ?v1 . ?v1 p2 ?v2 . ?v2 p3 ?v3 . ?v3 p4 ?v4, written as a left-deep chain. */
	private static TupleExpr filteredChain() {
		TupleExpr chain = new Join(new Join(new Join(pattern("v0", "urn:p1", "v1"), pattern("v1", "urn:p2", "v2")),
				pattern("v2", "urn:p3", "v3")), pattern("v3", "urn:p4", "v4"));
		return new Filter(chain,
				new Compare(Var.of("v2"), new ValueConstant(VALUES.createIRI("urn:x")), Compare.CompareOp.EQ));
	}

	/** SELECT ?v0 ?v4 over the same chain: the projection is offered after the chain's join region is searched. */
	private static TupleExpr projectedChain() {
		TupleExpr chain = new Join(new Join(new Join(pattern("v0", "urn:p1", "v1"), pattern("v1", "urn:p2", "v2")),
				pattern("v2", "urn:p3", "v3")), pattern("v3", "urn:p4", "v4"));
		return new Projection(chain, new ProjectionElemList(new ProjectionElem("v0"), new ProjectionElem("v4")));
	}

	private static StatementPattern pattern(String subject, String predicate, String object) {
		return new StatementPattern(Var.of(subject), Var.of(predicate.substring(4) + "Predicate",
				VALUES.createIRI(predicate), true, true), Var.of(object));
	}

	private static double rows(PackedQueryView query, int relationId) {
		return switch (query.statementPatternValue(relationId, 1).stringValue()) {
		case "urn:p1" -> 40.0d;
		case "urn:p2" -> 300.0d;
		case "urn:p3" -> 7.0d;
		default -> 900.0d;
		};
	}

	/** Prices every pattern standalone and per invocation under any prefix. */
	private static PackedCostModel pricedModel() {
		return new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return query.isStatementPattern(relationId) ? rows(query, relationId) : Double.NaN;
			}

			@Override
			public void estimate(PackedQueryView query, int relationId, PackedCostContext context,
					PackedCostEstimate output) {
				if (!query.isStatementPattern(relationId)) {
					return;
				}
				double rows = rows(query, relationId);
				if (context.prefixRelationCount() == 0) {
					output.setRows(rows, rows);
					output.setLocalPhysicalCost(rows, 0.0d, 1.0d, 0.0d, 0.0d, 0.0d, 0.0d, rows, 0.0d, 0.0d);
					return;
				}
				double invocations = Math.max(1.0d, context.prefixRows());
				double contextual = invocations * Math.max(1.0d, rows / 50.0d);
				output.setContextualRows(contextual, contextual);
				output.setLocalPhysicalCost(contextual, invocations, invocations, 0.0d, 0.0d, 0.0d, 0.0d,
						contextual, 0.0d, 0.0d);
				output.setInvocations(invocations);
			}
		};
	}

	/** Knows the rows of every pattern but the work of no access, so no plan of the root is ever priced. */
	private static PackedCostModel neverPricedModel() {
		return new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return query.isStatementPattern(relationId) ? rows(query, relationId) : Double.NaN;
			}

			@Override
			public double estimateLocalWork(PackedQueryView query, int relationId, double outputRows) {
				return Double.NaN;
			}

			@Override
			public void estimate(PackedQueryView query, int relationId, PackedCostContext context,
					PackedCostEstimate output) {
				if (!query.isStatementPattern(relationId)) {
					return;
				}
				boolean contextual = context.prefixRelationCount() != 0;
				double invocations = contextual ? Math.max(1.0d, context.prefixRows()) : 1.0d;
				output.setRows(rows(query, relationId), Double.NaN);
				output.setLocalPhysicalCostPreservingUnknown(Double.NaN, Double.NaN, invocations, 0.0d, 0.0d, 0.0d,
						0.0d, Double.NaN, 0.0d, 0.0d, Double.NaN);
				if (contextual) {
					output.setInvocations(invocations);
				}
			}
		};
	}

	/** Operator skeleton: operator names and statement-pattern predicates, in pre-order. */
	private static List<String> shape(TupleExpr plan) {
		List<String> shape = new ArrayList<>();
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				shape.add(node instanceof StatementPattern pattern
						? "SP " + pattern.getPredicateVar().getValue()
						: node.getClass().getSimpleName());
				super.meetNode(node);
			}
		});
		return shape;
	}
}
